import static org.junit.jupiter.api.Assertions.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicInteger;
import javax.swing.SwingUtilities;
import org.junit.jupiter.api.Test;
import org.openstreetmap.josm.gui.layer.MainLayerManager;
import org.openstreetmap.josm.plugins.dawarich.*;

class CoordinatorBatchContractTest {
    private static QueryBounds query(){return new QueryBounds(-1,1,-1,1,LocalDate.now().minusDays(1),LocalDate.now(),ZoneId.of("UTC"),Instant.now());}
    private static ReferenceDataset data(String server,String id,QueryBounds q,int count){var pts=new ArrayList<ReferencePoint>();for(int i=0;i<count;i++)pts.add(new ReferencePoint(i+1,0,0,Instant.now().getEpochSecond()));return new ReferenceDataset(server,id,q,pts);}
    private static SourceRegistry registry(int count,boolean keys){var r=new SourceRegistry();r.setEndpoint("https://example.test",false);for(int i=0;i<count;i++){var s=r.add("S"+i);if(keys)r.setKey(s.id,"k"+i);}return r;}
    @Test void missingKeysAreReportedAndValidSourcesStillLoad()throws Exception{var r=registry(3,false);var rows=r.rows();r.setKey(rows.get(1).id,"valid");var calls=new AtomicInteger();var ex=Executors.newSingleThreadExecutor();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->{calls.incrementAndGet();return data(s,id,q,1);})){var x=t.start(query()).get(5,TimeUnit.SECONDS);assertEquals(3,x.sources().size());assertEquals(LoadReferenceTask.Status.PARTIAL,x.status(),x.sources().toString());assertEquals(2,x.sources().stream().filter(z->z.status()==LoadReferenceTask.Status.FAILED).count());assertEquals(1,calls.get());}finally{ex.shutdownNow();}}
    @Test void quotaIsFairAcrossSelectedSourcesAndReturnedDataIsBounded()throws Exception{var r=registry(3,true);var seen=new ArrayList<Long>();var ex=Executors.newSingleThreadExecutor();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->{seen.add(n);return data(s,id,q,1);})){var x=t.start(query()).get(5,TimeUnit.SECONDS);assertEquals(List.of(16666L,16666L,16666L),seen);assertEquals(16666,x.perSourceQuota());assertEquals(LoadReferenceTask.Status.COMPLETE,x.status(),x.sources().toString());}finally{ex.shutdownNow();}}
    @Test void sharedServerFailureSkipsRemainingSources()throws Exception{var r=registry(3,true);var calls=new AtomicInteger();var ex=Executors.newSingleThreadExecutor();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->{if(calls.incrementAndGet()==1)return data(s,id,q,1);throw new DawarichException(DawarichException.Category.SERVER,"Server unavailable");})){var x=t.start(query()).get(5,TimeUnit.SECONDS);assertEquals(2,calls.get());assertEquals(LoadReferenceTask.Status.COMPLETE,x.sources().get(0).status());assertEquals(LoadReferenceTask.Status.FAILED,x.sources().get(1).status());assertEquals(LoadReferenceTask.Status.SKIPPED,x.sources().get(2).status());assertEquals(LoadReferenceTask.Status.PARTIAL,x.status());}finally{ex.shutdownNow();}}
    @Test void cancellationMarksCurrentAndUnattemptedSources()throws Exception{var r=registry(3,true);var calls=new AtomicInteger();var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var ex=Executors.newSingleThreadExecutor();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->{int i=calls.incrementAndGet();if(i==1)return data(s,id,q,1);entered.countDown();try{release.await();}catch(InterruptedException interrupted){Thread.currentThread().interrupt();throw new IllegalStateException(interrupted);}return data(s,id,q,1);})){var f=t.start(query());assertTrue(entered.await(3,TimeUnit.SECONDS));t.cancel();release.countDown();var x=f.get(5,TimeUnit.SECONDS);assertEquals(LoadReferenceTask.Status.COMPLETE,x.sources().get(0).status());assertEquals(LoadReferenceTask.Status.CANCELLED,x.sources().get(1).status());assertEquals(LoadReferenceTask.Status.CANCELLED,x.sources().get(2).status());assertEquals(LoadReferenceTask.Status.CANCELLED,x.status());assertEquals(1,t.layersSnapshot().get(r.rows().get(0).id).pointCount());}finally{release.countDown();ex.shutdownNow();}}
    @Test void retainedLayerFailureAndReplacementCapacityAreExplicitAndNonDestructive()throws Exception{var r=registry(3,true);var rows=r.rows();var ex=Executors.newSingleThreadExecutor();var phase=new AtomicInteger();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->{int p=phase.get();if(p==0)return data(s,id,q,id.equals(rows.get(0).id)?30000:10000);if(id.equals(rows.get(0).id))throw new DawarichException(DawarichException.Category.AUTH,"Authentication failed");return data(s,id,q,20000);})){r.setEnabled(rows.get(1).id,false);r.setEnabled(rows.get(2).id,false);assertEquals(LoadReferenceTask.Status.COMPLETE,t.start(query()).get(10,TimeUnit.SECONDS).status());r.setEnabled(rows.get(0).id,false);r.setEnabled(rows.get(1).id,true);assertEquals(LoadReferenceTask.Status.COMPLETE,t.start(query()).get(10,TimeUnit.SECONDS).status());r.setEnabled(rows.get(1).id,false);r.setEnabled(rows.get(2).id,true);assertEquals(LoadReferenceTask.Status.COMPLETE,t.start(query()).get(10,TimeUnit.SECONDS).status());phase.set(1);r.setEnabled(rows.get(0).id,true);r.setEnabled(rows.get(1).id,true);var x=t.start(query()).get(10,TimeUnit.SECONDS);assertTrue(x.sources().get(0).stale());assertEquals(30000,x.sources().get(0).pointCount());assertTrue(x.sources().get(1).message().contains("capacity"));assertEquals(LoadReferenceTask.Status.FAILED,x.sources().get(1).status());assertEquals(10000,t.layersSnapshot().get(rows.get(1).id).pointCount());assertEquals(LoadReferenceTask.Status.FAILED,x.status());}finally{ex.shutdownNow();}}
    @Test void emptySelectionAndExecutorRejectionDoNotLeaveLoadingLatched()throws Exception{var r=registry(1,true);var ex=Executors.newSingleThreadExecutor();try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->data(s,id,q,1))){r.setEnabled(r.rows().get(0).id,false);assertThrows(IllegalStateException.class,()->t.start(query()));assertFalse(t.isLoading());r.setEnabled(r.rows().get(0).id,true);}finally{ex.shutdownNow();}var rejected=registry(1,true);try(var t=new LoadReferenceTask(rejected,new MainLayerManager(),cmd->{throw new RejectedExecutionException();},(s,id,k,q,n,b)->data(s,id,q,1))){assertThrows(RejectedExecutionException.class,()->t.start(query()));assertFalse(t.isLoading());}}
    @Test void finalListenerSeesIdleTaskAndMayStartNextBatch()throws Exception{var r=registry(1,true);var ex=Executors.newSingleThreadExecutor();var seen=new CountDownLatch(1);try(var t=new LoadReferenceTask(r,new MainLayerManager(),ex,(s,id,k,q,n,b)->data(s,id,q,1))){var observed=new AtomicInteger();t.setListener(x->{if(x.status()!=LoadReferenceTask.Status.LOADING){assertFalse(t.isLoading());observed.incrementAndGet();seen.countDown();}});var f=t.start(query());assertEquals(LoadReferenceTask.Status.COMPLETE,f.get(5,TimeUnit.SECONDS).status());assertTrue(seen.await(3,TimeUnit.SECONDS));assertEquals(1,observed.get());assertFalse(t.isLoading());}finally{ex.shutdownNow();}}
}
